//! Complex, real-world spreadsheets: pivot tables, charts/pictures/shapes/comments, hidden and
//! grouped rows, filters, merges, formulas, error values, number formats of every family, many
//! and oddly named sheets, encrypted files, a sheet over the row cap.
//!
//! The files live in `testdata/office/` and are **our own** (generated by `testdata/office/gen/`
//! with LibreOffice through UNO and with openpyxl; see its README). Each is read through the
//! production path (`load_workbook_sheet`) and what the grid shows is pinned.
//!
//! What konoma does NOT read (colours, borders, column widths, charts, pictures, shapes,
//! comments, conditional formats, validations, hidden rows/columns, outlines, filters, freeze
//! panes) is pinned as such: those tests say "current spec" in their names, so a change of spec is
//! a deliberate edit and not a silent one.
//!
//! Known bugs found while building these files are written as `#[ignore = "BUG: ..."]` tests that
//! assert the *correct* behaviour (so fixing the bug turns them green; see the report that came
//! with them). They are not pinned to the wrong output.
//!
//! The expected values for the pivot tables come from `testdata/office/expected/pivot.expected.json`,
//! computed by the generator from the source rows (not read back from the pivot).

use super::*;
use std::path::PathBuf;

// ---------------------------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------------------------

fn td(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/office")
        .join(name)
}

/// The path of a test file, or `None` (with a SKIP note) when `testdata/` is not there (the
/// published crate excludes it, like `samples/`).
fn file(name: &str) -> Option<PathBuf> {
    let p = td(name);
    if p.exists() {
        Some(p)
    } else {
        eprintln!("SKIP: testdata/office/{name} not found (excluded from the published crate)");
        None
    }
}

const EXTS: [&str; 3] = ["xlsx", "xls", "ods"];

/// The workbook with the cells of sheet `idx` loaded (production path).
fn open(path: &Path, idx: usize) -> Workbook {
    let wb = load_workbook_sheet(path, &LoadOptions::default(), idx)
        .unwrap_or_else(|e| panic!("{}: {e:?}", path.display()));
    assert!(
        wb.sheet_error.is_none(),
        "{}: sheet {idx}: {:?}",
        path.display(),
        wb.sheet_error
    );
    wb
}

fn names(wb: &Workbook) -> Vec<&str> {
    wb.sheets.iter().map(|s| s.name.as_str()).collect()
}

/// The display grid of the loaded sheet, trailing empty cells and rows trimmed.
fn grid(s: &Sheet) -> Vec<Vec<String>> {
    let mut g: Vec<Vec<String>> = (0..s.nrows)
        .map(|r| {
            let mut row: Vec<String> = (0..s.ncols).map(|c| s.display(r, c).to_string()).collect();
            while row.last().is_some_and(|x| x.is_empty()) {
                row.pop();
            }
            row
        })
        .collect();
    while g.last().is_some_and(|r| r.is_empty()) {
        g.pop();
    }
    g
}

/// Sheet `idx` of `file`: (workbook, index) so the caller can borrow the sheet.
fn sheet_wb(name: &str, idx: usize) -> Option<(Workbook, usize)> {
    let p = file(name)?;
    Some((open(&p, idx), idx))
}

fn json(name: &str) -> serde_json::Value {
    let p = td(&format!("expected/{name}"));
    serde_json::from_str(&std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{p:?}: {e}")))
        .unwrap()
}

fn num(s: &Sheet, r: usize, c: usize) -> f64 {
    match s.cell(r, c).map(|x| &x.value) {
        Some(CellValue::Int(i)) => *i as f64,
        Some(CellValue::Number(n)) => *n,
        other => panic!("not a number at r{} c{}: {other:?}", r + 1, c + 1),
    }
}

fn find_row(s: &Sheet, col: usize, text: &str) -> Option<usize> {
    (0..s.nrows).find(|&r| s.display(r, col) == text)
}

// ---------------------------------------------------------------------------------------------
// pivot tables
// ---------------------------------------------------------------------------------------------
//
// A pivot table is *cells* in the file (what the application computed when it saved), plus a pivot
// definition that konoma does not read. So konoma shows the saved aggregation as an ordinary grid:
// these tests pin that the values are exactly the sums computed from the source rows.

fn sums(exp: &serde_json::Value, key: &str, k: &str) -> f64 {
    exp[key][k].as_f64().unwrap_or_else(|| panic!("{key}/{k}"))
}

#[test]
fn pivot_sheets_are_listed_in_order_in_all_three_formats() {
    for ext in EXTS {
        let Some(p) = file(&format!("pivot.{ext}")) else {
            return;
        };
        let wb = open(&p, 0);
        assert_eq!(
            names(&wb),
            ["元データ", "ピボット", "ページ付き", "件数"],
            "{ext}"
        );
        assert_eq!(wb.hidden_sheets, 0, "{ext}");
    }
}

#[test]
fn pivot_source_data_is_complete() {
    let exp = json("pivot.expected.json");
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("pivot.{ext}"), 0) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!(s.nrows, 1 + exp["rows"].as_u64().unwrap() as usize, "{ext}");
        assert_eq!(
            grid(s)[0],
            ["地域", "商品", "月", "チャネル", "売上"],
            "{ext}"
        );
        // every source row sums to the expected grand total
        let total: f64 = (1..s.nrows).map(|r| num(s, r, 4)).sum();
        assert_eq!(total, exp["grand"].as_f64().unwrap(), "{ext}");
        // text with markup characters survives
        assert!(find_row(s, 1, "Pen & Ink <A>").is_some(), "{ext}");
    }
}

/// The main pivot (rows: region > product, columns: month, data: SUM of sales, with region
/// subtotals and grand totals): every cell is what the source rows add up to.
#[test]
fn pivot_main_table_matches_sums_computed_from_the_source_rows() {
    let exp = json("pivot.expected.json");
    let regions: Vec<String> = exp["regions"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let months: Vec<String> = exp["months"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let products: Vec<String> = exp["products"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("pivot.{ext}"), 1) else {
            return;
        };
        let s = &wb.sheets[i];
        // header: "地域", "商品", "1月".."6月", total (the second pivot starts at column M)
        let hr = find_row(s, 0, "地域").expect("pivot header row");
        assert_eq!(s.display(hr, 1), "商品", "{ext}");
        let mcol: Vec<usize> = months
            .iter()
            .map(|m| {
                (0..12)
                    .find(|&c| s.display(hr, c) == m)
                    .expect("month column")
            })
            .collect();
        let tcol = mcol[mcol.len() - 1] + 1;
        assert_eq!(s.display(hr, tcol), "Total Result", "{ext}");

        let mut pending: Vec<usize> = Vec::new(); // product rows waiting for their subtotal row
        let mut seen_products = 0;
        let mut seen_regions = Vec::new();
        for r in hr + 1..s.nrows {
            let a = s.display(r, 0);
            let b = s.display(r, 1);
            if products.iter().any(|p| p == b) {
                pending.push(r);
                continue;
            }
            // A subtotal row ("関西 Sum - 売上") closes a region's group.
            if let Some(region) = regions
                .iter()
                .find(|g| a.starts_with(g.as_str()) && a.contains("Sum"))
            {
                assert_eq!(
                    pending.len(),
                    products.len(),
                    "{ext} {region}: products in group"
                );
                for pr in pending.drain(..) {
                    let p = s.display(pr, 1);
                    seen_products += 1;
                    // the region label sits on the first product row (xlsx) or is blank
                    for (m, &c) in months.iter().zip(&mcol) {
                        let want = sums(&exp, "cell", &format!("{region}|{p}|{m}"));
                        assert_eq!(num(s, pr, c), want, "{ext} {region}/{p}/{m}");
                        assert_eq!(
                            s.display(pr, c),
                            format!("{want}"),
                            "{ext} display {region}/{p}/{m}"
                        );
                    }
                    let want = sums(&exp, "region_product_total", &format!("{region}|{p}"));
                    assert_eq!(num(s, pr, tcol), want, "{ext} {region}/{p} total");
                }
                // subtotal per month and overall
                for (m, &c) in months.iter().zip(&mcol) {
                    let want: f64 = products
                        .iter()
                        .map(|p| sums(&exp, "cell", &format!("{region}|{p}|{m}")))
                        .sum();
                    assert_eq!(num(s, r, c), want, "{ext} {region} subtotal {m}");
                }
                assert_eq!(
                    num(s, r, tcol),
                    sums(&exp, "region_subtotal", region),
                    "{ext} {region} subtotal"
                );
                seen_regions.push(region.clone());
                continue;
            }
            if a == "Total Result" {
                for (m, &c) in months.iter().zip(&mcol) {
                    assert_eq!(
                        num(s, r, c),
                        sums(&exp, "month_total", m),
                        "{ext} grand {m}"
                    );
                }
                assert_eq!(
                    num(s, r, tcol),
                    exp["grand"].as_f64().unwrap(),
                    "{ext} grand total"
                );
                break;
            }
        }
        assert_eq!(
            seen_regions.len(),
            regions.len(),
            "{ext}: every region has a subtotal row"
        );
        assert_eq!(seen_products, regions.len() * products.len(), "{ext}");
    }
}

/// A second pivot on the same sheet, to the right of the first (AVERAGE by product x channel).
#[test]
fn pivot_second_table_on_the_same_sheet_is_read_as_cells_next_to_the_first() {
    let exp = json("pivot.expected.json");
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("pivot.{ext}"), 1) else {
            return;
        };
        let s = &wb.sheets[i];
        assert!(
            s.ncols >= 16,
            "{ext}: both pivots are on the sheet ({} cols)",
            s.ncols
        );
        let hr = (0..s.nrows)
            .find(|&r| s.display(r, 12) == "商品")
            .expect("second pivot header");
        let (web, shop, tot) = (13, 14, 15);
        assert_eq!(
            (s.display(hr, web), s.display(hr, shop), s.display(hr, tot)),
            ("Web", "店舗", "Total Result"),
            "{ext}"
        );
        for p in ["りんご", "みかん", "Pen & Ink <A>", "ぶどう"] {
            let r = (hr + 1..s.nrows)
                .find(|&r| s.display(r, 12) == p)
                .unwrap_or_else(|| panic!("{ext} {p}"));
            for (c, ch) in [(web, "Web"), (shop, "店舗")] {
                let want = sums(&exp, "avg_by_product_channel", &format!("{p}|{ch}"));
                assert!(
                    (num(s, r, c) - want).abs() < 1e-9,
                    "{ext} {p}/{ch}: {} vs {want}",
                    num(s, r, c)
                );
            }
            let want = sums(&exp, "avg_by_product", p);
            assert!((num(s, r, tot) - want).abs() < 1e-9, "{ext} {p} total");
        }
        let r = (hr + 1..s.nrows)
            .find(|&r| s.display(r, 12) == "Total Result")
            .unwrap();
        assert!(
            (num(s, r, web) - sums(&exp, "avg_by_channel", "Web")).abs() < 1e-9,
            "{ext}"
        );
        assert!(
            (num(s, r, shop) - sums(&exp, "avg_by_channel", "店舗")).abs() < 1e-9,
            "{ext}"
        );
        assert!(
            (num(s, r, tot) - exp["avg_all"].as_f64().unwrap()).abs() < 1e-9,
            "{ext}"
        );
        // General is shown the way Excel shows it in a default-width column: 10 significant digits
        let r = (hr + 1..s.nrows)
            .find(|&r| s.display(r, 12) == "ぶどう")
            .unwrap();
        assert_eq!(s.display(r, web), "722.9166667", "{ext}");
    }
}

/// The page (report filter) field is two cells ("地域", "関東") above the table, and the table below
/// shows only that region.
#[test]
fn pivot_with_a_page_filter_shows_the_filter_cells_and_only_the_filtered_totals() {
    let exp = json("pivot.expected.json");
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("pivot.{ext}"), 2) else {
            return;
        };
        let s = &wb.sheets[i];
        let fr = find_row(s, 0, "地域").expect("page field row");
        assert_eq!(s.display(fr, 1), "関東", "{ext}: the selected page");
        let hr = find_row(s, 0, "商品").expect("header");
        for p in ["りんご", "みかん", "Pen & Ink <A>", "ぶどう"] {
            let r = find_row(s, 0, p).unwrap_or_else(|| panic!("{ext} {p}"));
            for (k, m) in ["1月", "2月", "3月", "4月", "5月", "6月"]
                .iter()
                .enumerate()
            {
                assert_eq!(s.display(hr, 1 + k), *m, "{ext}");
                let want = sums(&exp, "cell", &format!("関東|{p}|{m}"));
                assert_eq!(num(s, r, 1 + k), want, "{ext} {p}/{m}");
            }
        }
        let r = find_row(s, 0, "Total Result").unwrap();
        assert_eq!(
            num(s, r, 7),
            exp["kanto_only_grand"].as_f64().unwrap(),
            "{ext}"
        );
    }
}

#[test]
fn pivot_count_table_shows_counts() {
    let exp = json("pivot.expected.json");
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("pivot.{ext}"), 3) else {
            return;
        };
        let s = &wb.sheets[i];
        let hr = find_row(s, 0, "地域").unwrap();
        let (web, shop, tot) = (
            (1..4).find(|&c| s.display(hr, c) == "Web").unwrap(),
            (1..4).find(|&c| s.display(hr, c) == "店舗").unwrap(),
            (1..4)
                .find(|&c| s.display(hr, c) == "Total Result")
                .unwrap(),
        );
        for region in ["北海道", "関東", "関西", "九州"] {
            let r = find_row(s, 0, region).unwrap();
            assert_eq!(
                num(s, r, web),
                sums(&exp, "count_by_region_channel", &format!("{region}|Web")),
                "{ext}"
            );
            assert_eq!(
                num(s, r, shop),
                sums(&exp, "count_by_region_channel", &format!("{region}|店舗")),
                "{ext}"
            );
            assert_eq!(num(s, r, tot), 24.0, "{ext}");
        }
        let r = find_row(s, 0, "Total Result").unwrap();
        assert_eq!(
            (num(s, r, web), num(s, r, shop), num(s, r, tot)),
            (48.0, 48.0, 96.0),
            "{ext}"
        );
    }
}

