// ---------------------------------------------------------------------------------------------
// objects: chart, picture, shape, text box, comment, conditional format, validation, hyperlink
// ---------------------------------------------------------------------------------------------

#[test]
fn objects_cells_around_charts_pictures_shapes_and_comments_are_read_normally() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("objects.{ext}"), 0) else {
            return;
        };
        assert_eq!(names(&wb), ["売上", "図形のみ"], "{ext}");
        assert_eq!(wb.hidden_sheets, 0, "{ext}");
        let s = &wb.sheets[i];
        let g = grid(s);
        assert_eq!(g[0][..5], ["月", "売上", "前年", "備考", "選択"], "{ext}");
        assert_eq!(
            g[1][..5],
            ["1月", "120", "100", "好調 \u{1F600}", "みかん"],
            "{ext}"
        );
        assert_eq!(g[2][..4], ["2月", "150", "130", "Tom & Jerry <b>"], "{ext}");
        assert_eq!(g[5][..3], ["5月", "175", "150"], "{ext}");
        // a formula below the chart's area keeps its value (and its row position)
        assert_eq!(s.nrows, 30, "{ext}");
        assert_eq!(s.display(29, 0), "グラフの下の行", "{ext}");
        assert_eq!(s.display(29, 1), "735", "{ext}");
        assert!(
            s.formula(29, 1).is_some_and(|f| f.contains("SUM")),
            "{ext}: {:?}",
            s.formula(29, 1)
        );
    }
}

/// Current spec (§6): the comment, the shape's text, the chart and the picture are not read.
#[test]
fn objects_comments_shapes_charts_and_pictures_are_not_shown_current_spec() {
    for ext in EXTS {
        for idx in [0, 1] {
            let Some((wb, i)) = sheet_wb(&format!("objects.{ext}"), idx) else {
                return;
            };
            let all: String = grid(&wb.sheets[i])
                .iter()
                .flatten()
                .cloned()
                .collect::<Vec<_>>()
                .join("|");
            for hidden_text in [
                "コメント",
                "先月比",
                "備考のコメント",
                "図形のテキスト",
                "テキストボックス",
                "グラフ1",
            ] {
                assert!(
                    !all.contains(hidden_text),
                    "{ext} sheet {idx}: {hidden_text:?} must not be a cell"
                );
            }
        }
    }
}

#[test]
fn objects_hyperlinks_show_their_text_not_their_target() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("objects.{ext}"), 0) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!(
            s.display(0, 6),
            "例のリンク",
            "{ext}: HYPERLINK() formula shows its label"
        );
        assert_eq!(
            s.display(1, 6),
            "URL フィールド",
            "{ext}: URL field shows its representation"
        );
        let all: String = grid(s).iter().flatten().cloned().collect();
        assert!(
            !all.contains("example.com") && !all.contains("example.org"),
            "{ext}"
        );
    }
}

