// ---------------------------------------------------------------------------------------------
// layout: hidden rows / columns, outline, filter, merges, wrapping, protection
// ---------------------------------------------------------------------------------------------

/// Current spec (§6): konoma does not read row/column visibility. Hidden columns B and D and
/// hidden rows 5 and 6 are all shown. (A file where a hidden row holds secrets would show them.)
#[test]
fn layout_hidden_rows_and_columns_are_all_shown_current_spec() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("layout.{ext}"), 0) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!((s.nrows, s.ncols), (12, 5), "{ext}");
        assert_eq!(
            s.display(1, 1),
            "B列(非表示)",
            "{ext}: hidden column B is shown"
        );
        assert_eq!(
            s.display(1, 3),
            "D列(非表示)",
            "{ext}: hidden column D is shown"
        );
        assert_eq!(
            grid(s)[4],
            ["r5a", "r5b", "r5c", "r5d", "r5e"],
            "{ext}: hidden row 5 is shown"
        );
        assert_eq!(
            grid(s)[5],
            ["r6a", "r6b", "r6c", "r6d", "r6e"],
            "{ext}: hidden row 6 is shown"
        );
    }
}

/// Current spec: rows 3..7 are grouped and collapsed (hidden) in the file; all ten rows are shown.
#[test]
fn layout_collapsed_outline_rows_are_all_shown_current_spec() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("layout.{ext}"), 1) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!(s.nrows, 10, "{ext}");
        for r in 0..10 {
            assert_eq!(s.display(r, 0), format!("行{}", r + 1), "{ext}");
            assert_eq!(num(s, r, 1), 10.0 * (r as f64 + 1.0), "{ext}");
        }
    }
}

/// Current spec: an auto-filter (value > 50) hides rows 2..6 in the file; all rows are shown.
#[test]
fn layout_rows_hidden_by_an_autofilter_are_all_shown_current_spec() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("layout.{ext}"), 2) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!(s.nrows, 11, "{ext}");
        assert_eq!(grid(s)[0], ["地域", "売上"], "{ext}");
        for r in 1..=10 {
            assert_eq!(
                num(s, r, 1),
                10.0 * r as f64,
                "{ext}: row {} (filtered out in Excel) is shown",
                r + 1
            );
        }
        assert_eq!(s.display(1, 0), "西1", "{ext}");
        assert_eq!(s.display(10, 0), "東10", "{ext}");
    }
}

#[test]
fn layout_merged_cells_show_their_value_at_the_top_left_only() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("layout.{ext}"), 3) else {
            return;
        };
        let s = &wb.sheets[i];
        assert_eq!(s.display(0, 0), "見出し(3行×4列の結合)", "{ext}");
        for (r, c) in [
            (0, 1),
            (0, 3),
            (1, 0),
            (2, 3),
            (4, 1),
            (4, 2),
            (5, 4),
            (7, 4),
        ] {
            assert_eq!(
                s.display(r, c),
                "",
                "{ext}: r{} c{} is covered by a merge",
                r + 1,
                c + 1
            );
        }
        assert_eq!(s.display(4, 0), "横結合", "{ext}");
        assert_eq!(s.display(4, 4), "縦結合", "{ext}");
        assert_eq!(s.display(8, 0), "結合の隣", "{ext}");
        assert_eq!(num(s, 8, 1), 42.0, "{ext}");
    }
}

fn mr(row0: u32, col0: u32, row1: u32, col1: u32) -> MergeRange {
    MergeRange {
        row0,
        col0,
        row1,
        col1,
    }
}

#[test]
fn layout_merged_ranges_are_reported_for_xlsx_and_xls() {
    for ext in ["xlsx", "xls"] {
        let Some((wb, i)) = sheet_wb(&format!("layout.{ext}"), 3) else {
            return;
        };
        let mut m = wb.sheets[i].merges.clone();
        m.sort_by_key(|r| (r.row0, r.col0));
        assert_eq!(m, [mr(0, 0, 2, 3), mr(4, 0, 4, 2), mr(4, 4, 7, 4)], "{ext}");
    }
}

