#[test]
fn formulas_show_the_value_saved_with_the_file() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("formulas.{ext}"), 1) else {
            return;
        };
        assert_eq!(
            names(&wb),
            ["入力", "計算", "エラー", "配列", "揮発"],
            "{ext}"
        );
        let s = &wb.sheets[i];
        let want: [(usize, &str); 13] = [
            (0, "20"),             // SUM(named range)
            (1, "360"),            // 'input'.B2 * 'input'.C2 (cross-sheet)
            (2, "2010"),           // SUMPRODUCT across sheets
            (3, "2211"),           // ROUND(B3*(1+named cell))
            (4, "合計: 2,010 円"), // text concatenation with TEXT()
            (5, "TRUE"),           // boolean result
            (6, "80"),             // VLOOKUP
            (7, "高い"),
            (9, "0.3"), // 0.1+0.2
            (10, "1E+300"),
            (11, "1E-300"),
            (12, ""), // ="" is an empty string result
            (13, "あああああ"),
        ];
        for (r, v) in want {
            assert_eq!(s.display(r, 1), v, "{ext} 計算!B{}", r + 1);
        }
        // the formulas themselves are available for the cell detail
        for r in [0, 1, 2, 3, 4, 5, 6, 7] {
            assert!(
                s.formula(r, 1).is_some(),
                "{ext} 計算!B{} has a formula",
                r + 1
            );
        }
        assert!(
            s.formula(1, 1).unwrap().contains("入力"),
            "{ext}: {:?}",
            s.formula(1, 1)
        );
        // a formula result that is a date is a date, shown with the saved format
        assert!(
            matches!(
                s.cell(8, 1).unwrap().value,
                CellValue::DateTime { .. } | CellValue::DateTimeIso(_)
            ),
            "{ext}"
        );
        assert_eq!(s.cell(5, 1).unwrap().cell_type(), CellType::Bool, "{ext}");
    }
}

