/// Volatile functions: whatever the file saved is shown, never recalculated; the kind is right.
#[test]
fn formulas_volatile_functions_show_their_saved_values() {
    for ext in EXTS {
        let Some((wb, i)) = sheet_wb(&format!("formulas.{ext}"), 4) else {
            return;
        };
        let s = &wb.sheets[i];
        assert!(
            matches!(
                s.cell(0, 0).unwrap().value,
                CellValue::DateTime { .. } | CellValue::DateTimeIso(_)
            ),
            "{ext} NOW()"
        );
        assert!(
            matches!(
                s.cell(1, 0).unwrap().value,
                CellValue::DateTime { .. } | CellValue::DateTimeIso(_)
            ),
            "{ext} TODAY()"
        );
        let r = num(s, 2, 0);
        assert!((0.0..1.0).contains(&r), "{ext} RAND() = {r}");
        // the year of NOW() in the file is the year it was made
        assert!(
            s.display(0, 0).contains("/26 ") || s.display(0, 0).contains("2026"),
            "{ext}: {}",
            s.display(0, 0)
        );
        assert_eq!(s.display(3, 0), "00:00:00", "{ext}: NOW()-NOW()");
    }
}

