/// What Excel shows (English UI), for `formats.xlsx` and `formats.xls`. Row index = case index + 1.
/// Cases where Excel's own text is not certain (sub-second rounding) are not pinned here.
const FORMATS_EXCEL: &[(&str, &str)] = &[
    ("和暦(令和)", "令和8年10月5日"),
    ("和暦(平成1年)", "平成1年1月8日"),
    ("和暦(昭和)", "昭和55年04月29日"),
    ("西暦 日本語曜日", "2026年10月05日 (月)"),
    ("英語曜日・月名", "Monday, October 5, 2026"),
    ("ISO 日付", "2026-10-05"),
    ("24 時間超 [h]:mm:ss", "36:00:00"),
    ("100.25 日 [h]:mm", "2406:00"),
    ("経過分 [mm]:ss", "61:12"),
    ("時刻 AM/PM", "1:30 PM"),
    ("負数の赤", "-1,235"),
    ("負数の括弧(赤)", "(1,234.50)"),
    ("正数", "1,235"),
    ("ゼロ区画", "ゼロ"),
    ("分数 # ?/?", " 3/4"),
    ("分数 帯分数", "3 14/99"),
    ("指数 0.00E+00", "1.23E+04"),
    ("指数 ##0.0E+0", "12.3E+3"),
    ("指数 微小", "1.23E-04"),
    ("通貨 円", "¥1,500"),
    ("通貨 円 負", "-¥1,500"),
    ("通貨 ユーロ", "€ 1,234.50"),
    ("通貨 ドル", "$1,234.50"),
    ("通貨 ウォン", "₩1,234,567"),
    ("通貨 ポンド", "£99.50"),
    ("パーセント", "25.6%"),
    ("千単位", "1,235K"),
    ("条件付き", "12.3万"),
    ("色と条件", "-5"),
    ("ゼロ詰め", "000123"),
    ("電話番号", "090-1234-5678"),
    ("テキスト書式 @", "00123"),
    ("文字列に書式", "【あいう】"),
    ("会計 _ と *", " 1,234.50 "),
    ("丸め 0.5 → 1", "1"),
    ("丸め 2.5 → 3", "3"),
    ("丸め 0.285 小数2", "0.29"),
    ("日付+時刻", "2026/10/05 18:00:00"),
    // Excel's serial 0 is "1900-01-00" and serial 60 is the non-existent 1900-02-29
    ("通し日付 0", "1900-01-00"),
    ("1900 閏年 60", "1900-02-29"),
    // General in a default-width column: at most ~11 characters (Excel switches to E notation)
    ("大きい数 General", "1.23457E+11"),
    ("小数 General", "0.333333333"),
];

fn formats_by_label(s: &Sheet) -> std::collections::HashMap<String, String> {
    (1..s.nrows)
        .map(|r| (s.display(r, 0).to_string(), s.display(r, 1).to_string()))
        .collect()
}

#[test]
fn formats_xlsx_and_xls_show_what_excel_shows() {
    for ext in ["xlsx", "xls"] {
        let Some((wb, i)) = sheet_wb(&format!("formats.{ext}"), 0) else {
            return;
        };
        let m = formats_by_label(&wb.sheets[i]);
        assert_eq!(m.len(), 43, "{ext}: every case row is there");
        for (label, want) in FORMATS_EXCEL {
            assert_eq!(
                m.get(*label).map(String::as_str),
                Some(*want),
                "{ext}: {label}"
            );
        }
    }
}

/// Sub-second display: 0.000694444 d is 59.99999 s. Excel carries into the minute.
#[test]
fn formats_fractional_seconds_carry_instead_of_showing_sixty() {
    let Some((wb, i)) = sheet_wb("formats.xlsx", 0) else {
        return;
    };
    let m = formats_by_label(&wb.sheets[i]);
    let v = &m["時刻 小数秒"];
    assert!(v == "01:00.00" || v == "00:59.99", "{v}");
    assert!(!v.contains(":60"), "{v}");
}

#[test]
fn formats_ods_matches_excel_for_every_family() {
    let Some((wb, i)) = sheet_wb("formats.ods", 0) else {
        return;
    };
    let m = formats_by_label(&wb.sheets[i]);
    let skip = [
        // LibreOffice's day 0 is 1899-12-30 (Excel's is "1900-01-00"): checked below
        "通し日付 0",
        // the weekday name `aaa` is English here: an ods style carries no locale for it
        "西暦 日本語曜日",
        // ods stores real dates (no serial): 1900-02-29 cannot exist, LibreOffice's 1900-02-28
        "1900 閏年 60",
        // General: not the same in ods (checked below)
        "大きい数 General",
        "小数 General",
    ];
    for (label, want) in FORMATS_EXCEL {
        if skip.contains(label) {
            continue;
        }
        assert_eq!(
            m.get(*label).map(String::as_str),
            Some(*want),
            "ods: {label}"
        );
    }
    assert_eq!(m["通し日付 0"], "1899-12-30");
    assert_eq!(m["西暦 日本語曜日"], "2026年10月05日 (Mon)");
    assert_eq!(m["1900 閏年 60"], "1900-02-28");
    assert_eq!(m["大きい数 General"], "1.23457E+11");
    assert_eq!(m["小数 General"], "0.333333333");
}

