#[test]
fn special_excel_table_is_plain_cells_with_its_header() {
    let Some((wb, i)) = sheet_wb("special.xlsx", 0) else {
        return;
    };
    let s = &wb.sheets[i];
    assert_eq!(grid(s)[0][..4], ["地域", "商品", "数量", "金額"]);
    assert_eq!(grid(s)[1][..4], ["東", "りんご", "3", "360"]);
    assert_eq!(grid(s)[5][..4], ["東", "みかん", "1", "80"]);
}

#[test]
fn special_inline_strings_string_formula_results_and_typed_cells() {
    let Some((wb, i)) = sheet_wb("special.xlsx", 0) else {
        return;
    };
    let s = &wb.sheets[i];
    // row 8: t="inlineStr", t="str" with a formula, t="str" value only, t="b", t="e"
    assert_eq!(s.display(7, 0), "インライン文字列");
    assert_eq!(s.cell(7, 0).unwrap().cell_type(), CellType::Text);
    assert_eq!(s.display(7, 1), "ab");
    assert_eq!(s.formula(7, 1), Some("\"a\"&\"b\""));
    assert_eq!(s.display(7, 2), "str-typed value");
    assert_eq!(s.display(7, 3), "TRUE");
    assert_eq!(s.cell(7, 3).unwrap().cell_type(), CellType::Bool);
    assert_eq!(s.display(7, 4), "#REF!");
}

#[test]
fn special_rich_text_shows_its_plain_text_and_escapes_are_decoded() {
    let Some((wb, i)) = sheet_wb("special.xlsx", 1) else {
        return;
    };
    let s = &wb.sheets[i];
    assert_eq!(
        s.display(0, 0),
        "普通太字赤 と 斜体",
        "rich text runs are joined"
    );
    assert_eq!(
        s.display(1, 0),
        "  leading and trailing  ",
        "xml:space=preserve"
    );
    assert_eq!(s.display(2, 0), "line1\nline2");
    assert_eq!(s.display(3, 0), "x\u{b}vt", "_x000B_ is a vertical tab");
    assert_eq!(
        s.display(4, 0),
        "A literal escape text",
        "_x0041_ is the letter A"
    );
}

#[test]
fn special_dates_times_durations_booleans_errors_and_extreme_numbers() {
    let Some((wb, i)) = sheet_wb("special.xlsx", 1) else {
        return;
    };
    let s = &wb.sheets[i];
    assert_eq!(s.display(5, 0), "2026-10-05 13:30:15");
    assert_eq!(s.display(6, 0), "2026-10-05");
    assert_eq!(s.display(7, 0), "7:05:09");
    assert_eq!(s.display(8, 0), "36:30:00");
    assert_eq!((s.display(0, 1), s.display(1, 1)), ("TRUE", "FALSE"));
    assert_eq!((s.display(2, 1), s.display(3, 1)), ("#DIV/0!", "#N/A"));
    assert_eq!(s.display(0, 2), "1.5E+300");
    assert_eq!(s.display(1, 2), "0", "negative zero is shown as 0");
    assert_eq!(s.display(2, 2), "123456789.1");
    assert_eq!(s.display(3, 2), "1E+15");
    assert_eq!(s.display(4, 2), "9.0072E+15");
}

