#[test]
fn encrypted_xlsx_and_xls_are_reported_as_encrypted() {
    for ext in ["xlsx", "xls"] {
        let Some(p) = file(&format!("encrypted.{ext}")) else {
            return;
        };
        assert_eq!(
            load_workbook_sheet(&p, &LoadOptions::default(), 0),
            Err(OfficeError::Encrypted),
            "{ext}"
        );
        assert_eq!(
            load_workbook(&p, &LoadOptions::default()),
            Err(OfficeError::Encrypted),
            "{ext}"
        );
    }
}

/// LibreOffice 25+ encrypts an ods as one `encrypted-package` entry (AES-GCM, Argon2). The package
/// has no `content.xml`; the clear `mimetype` and the manifest tell it is an encrypted spreadsheet.
#[test]
fn encrypted_ods_is_reported_as_encrypted() {
    let Some(p) = file("encrypted.ods") else {
        return;
    };
    assert_eq!(
        load_workbook_sheet(&p, &LoadOptions::default(), 0),
        Err(OfficeError::Encrypted)
    );
}

/// Whatever the reason, an encrypted ods is refused without a panic or a hang (today: Unsupported).
#[test]
fn encrypted_ods_is_refused_cleanly() {
    let Some(p) = file("encrypted.ods") else {
        return;
    };
    let r = load_workbook_sheet(&p, &LoadOptions::default(), 0);
    assert!(
        matches!(
            r,
            Err(OfficeError::Encrypted) | Err(OfficeError::Unsupported)
        ),
        "{r:?}"
    );
}

// ---------------------------------------------------------------------------------------------
// a sheet over the row cap
// ---------------------------------------------------------------------------------------------

/// 120,000 data rows x 3 columns plus a small second sheet, as an xlsx (generated here: a file this
/// size is not kept in the repository).
fn big_xlsx(dir: &crate::test_support::TmpDir) -> PathBuf {
    let mut rows = String::from(
        r#"<row r="1"><c r="A1" t="inlineStr"><is><t>行番号</t></is></c><c r="B1" t="inlineStr"><is><t>二乗</t></is></c><c r="C1" t="inlineStr"><is><t>ラベル</t></is></c></row>"#,
    );
    for i in 1..=120_000u64 {
        let r = i + 1;
        rows += &format!(
            r#"<row r="{r}"><c r="A{r}"><v>{i}</v></c><c r="B{r}"><v>{}</v></c><c r="C{r}" t="inlineStr"><is><t>行{i}</t></is></c></row>"#,
            i * i
        );
    }
    let small = r#"<row r="1"><c r="A1" t="inlineStr"><is><t>小さいシート</t></is></c></row>"#;
    let p = dir.join("big.xlsx");
    crate::e2e_tests::build_xlsx(
        &p,
        &[("大", "visible", &rows, ""), ("小", "visible", small, "")],
    );
    p
}

/// The same workbook as an ods.
fn big_ods(dir: &crate::test_support::TmpDir) -> PathBuf {
    const NS: &str = concat!(
        r#"xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" "#,
        r#"xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" "#,
        r#"xmlns:table="urn:oasis:names:tc:opendocument:xmlns:table:1.0""#
    );
    let s = |t: &str| {
        format!(
            r#"<table:table-cell office:value-type="string"><text:p>{t}</text:p></table:table-cell>"#
        )
    };
    let f = |v: u64| {
        format!(
            r#"<table:table-cell office:value-type="float" office:value="{v}"><text:p>{v}</text:p></table:table-cell>"#
        )
    };
    let mut rows = format!(
        "<table:table-row>{}{}{}</table:table-row>",
        s("行番号"),
        s("二乗"),
        s("ラベル")
    );
    for i in 1..=120_000u64 {
        rows += &format!(
            "<table:table-row>{}{}{}</table:table-row>",
            f(i),
            f(i * i),
            s(&format!("行{i}"))
        );
    }
    let content = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><office:document-content {NS} office:version="1.3"><office:body><office:spreadsheet><table:table table:name="大">{rows}</table:table><table:table table:name="小"><table:table-row>{}</table:table-row></table:table></office:spreadsheet></office:body></office:document-content>"#,
        s("小さいシート")
    );
    let manifest = r#"<?xml version="1.0" encoding="UTF-8"?><manifest:manifest xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0" manifest:version="1.3"><manifest:file-entry manifest:full-path="/" manifest:media-type="application/vnd.oasis.opendocument.spreadsheet"/><manifest:file-entry manifest:full-path="content.xml" manifest:media-type="text/xml"/></manifest:manifest>"#;
    let bytes = tests::deflated(&[
        (
            "mimetype",
            b"application/vnd.oasis.opendocument.spreadsheet",
        ),
        ("content.xml", content.as_bytes()),
        ("META-INF/manifest.xml", manifest.as_bytes()),
    ]);
    let p = dir.join("big.ods");
    std::fs::write(&p, bytes).unwrap();
    p
}

#[test]
fn big_sheet_shows_its_beginning_and_is_marked_capped() {
    let cap = LoadOptions::default().limits.max_rows;
    let dir = tests::tmp("complex_big");
    for (ext, p) in [("xlsx", big_xlsx(&dir)), ("ods", big_ods(&dir))] {
        let wb = open(&p, 0);
        assert_eq!(names(&wb), ["大", "小"], "{ext}");
        let s = &wb.sheets[0];
        assert!(
            s.rows_truncated,
            "{ext}: 120,000 rows is over the cap of {cap}"
        );
        assert!(
            s.nrows <= cap + 1 && s.nrows >= cap,
            "{ext}: {} rows",
            s.nrows
        );
        assert_eq!(grid(s)[0], ["行番号", "二乗", "ラベル"], "{ext}");
        assert_eq!(grid(s)[1], ["1", "1", "行1"], "{ext}");
        assert_eq!(grid(s)[1000], ["1000", "1000000", "行1000"], "{ext}");
        // the last kept row is a real row of the file, not a partial one
        let last = s.nrows - 1;
        assert_eq!(s.display(last, 0), last.to_string(), "{ext}");
        assert_eq!(s.display(last, 2), format!("行{last}"), "{ext}");
        // the second sheet is still reachable on its own
        let wb2 = open(&p, 1);
        assert_eq!(wb2.sheets[1].display(0, 0), "小さいシート", "{ext}");
        assert!(!wb2.sheets[1].rows_truncated, "{ext}");
    }
}
